const items = $input.all();
const body = items[0].json.body || items[0].json;

// Solo procesar messages.upsert
const event = body.event || '';
if (event !== 'messages.upsert') {
  return [{ json: { phone: '', respuesta: '', needsAPI: false, intent: '' } }];
}

const data = body.data || {};
const key = data.key || {};

// Ignorar mensajes propios y de grupos
if (key.fromMe || (key.remoteJid || '').includes('@g.us')) {
  return [{ json: { phone: '', respuesta: '', needsAPI: false, intent: '' } }];
}

// Extraer texto
const msg = data.message || {};
const text = (msg.conversation || (msg.extendedTextMessage && msg.extendedTextMessage.text) || '').trim();
if (!text) {
  return [{ json: { phone: '', respuesta: '', needsAPI: false, intent: '' } }];
}

const phone = (key.remoteJid || '').replace('@s.whatsapp.net', '');
let comando = text.toLowerCase().trim();
const API = 'https://api-sg.hato-pascher.com';

// Atajos num\u00e9ricos: expandir n\u00famero a comando
const atajos = { '1': 'catalogo', '2': 'buscar', '3': 'precio', '4': 'abono', '5': 'pedido' };
const partes = comando.split(/\s+/);
if (atajos[partes[0]]) {
  partes[0] = atajos[partes[0]];
  comando = partes.join(' ');
}

let respuesta = '';
let needsAPI = false;
let apiUrl = '';
let intent = '';
let args = '';

if (['menu', 'hola', 'ayuda', 'hi', 'hello', 'inicio', '0'].includes(comando)) {
  intent = 'menu';
  respuesta = '*\ud83c\udfed El Hato Pascher C.A.*\n\n' +
    'Escribe el n\u00famero o el comando:\n\n' +
    '*1.* \ud83d\udce6 *catalogo* \u2014 lista de productos\n' +
    '*2.* \ud83d\udd0d *buscar [texto]* \u2014 buscar producto\n' +
    '*3.* \ud83d\udcb2 *precio [c\u00f3digo]* \u2014 precio de un producto\n' +
    '*4.* \ud83d\udcdd *abono [PIN]* \u2014 consulta de cuenta (personal)\n' +
    '*5.* \ud83d\uded2 *pedido* \u2014 hacer un pedido\n\n' +
    '_Ejemplo: 2 slalon  \u00f3  buscar slalon_';

} else if (comando === 'catalogo' || comando === 'productos') {
  intent = 'catalogo';
  needsAPI = true;
  apiUrl = API + '/api/wa/catalogo';

} else if (comando.startsWith('buscar ')) {
  intent = 'buscar';
  args = comando.slice(7).trim();
  if (!args) {
    respuesta = 'Escribe qu\u00e9 producto buscas.\n_Ejemplo: 2 slalon_';
  } else {
    needsAPI = true;
    apiUrl = API + '/api/wa/catalogo?q=' + encodeURIComponent(args);
  }

} else if (comando === 'buscar') {
  intent = 'buscar';
  respuesta = 'Escribe qu\u00e9 producto buscas.\n_Ejemplo: 2 slalon_';

} else if (comando.startsWith('precio ')) {
  intent = 'precio';
  args = comando.slice(7).trim();
  if (!args) {
    respuesta = 'Escribe el c\u00f3digo del producto.\n_Ejemplo: 3 771000_';
  } else {
    needsAPI = true;
    apiUrl = API + '/api/wa/producto/' + encodeURIComponent(args);
  }

} else if (comando === 'precio') {
  intent = 'precio';
  respuesta = 'Escribe el c\u00f3digo del producto.\n_Ejemplo: 3 771000_';

} else if (comando.startsWith('abono ') || comando.startsWith('estado ') || comando.startsWith('pagos ') || comando.startsWith('abonos ')) {
  intent = 'abono';
  const prefijos = ['abono ', 'estado ', 'pagos ', 'abonos '];
  const prefijo = prefijos.find(p => comando.startsWith(p));
  args = comando.slice(prefijo.length).trim();
  if (!args) {
    respuesta = 'Escribe el PIN del cliente.\n_Ejemplo: 4 1234_';
  } else {
    needsAPI = true;
    apiUrl = API + '/api/wa/estado-cuenta?pin=' + encodeURIComponent(args) + '&tel=' + phone;
  }

} else if (['abono', 'estado', 'pagos', 'abonos'].includes(comando)) {
  intent = 'abono';
  respuesta = 'Escribe el PIN del cliente.\n_Ejemplo: 4 1234_';

} else if (comando === 'pedido') {
  intent = 'pedido_ayuda';
  respuesta = '*\ud83d\uded2 Realizar Pedido*\n\n' +
    'Env\u00eda tu pedido en un solo mensaje con este formato:\n\n' +
    '*pedido Nombre, Tel\u00e9fono, productos*\n\n' +
    '_Ejemplo:_\n' +
    '_pedido Juan P\u00e9rez, 0414-1234567, 2 TUB001, 5 SLA002, 1 CEM003_\n\n' +
    'Puedes usar los c\u00f3digos del *cat\u00e1logo* (escribe 1).';

} else if (comando.startsWith('pedido ')) {
  intent = 'pedido';
  // Parsear: pedido Nombre, Telefono, productos...
  const contenido = text.slice(7).trim();
  const segmentos = contenido.split(',').map(s => s.trim());
  if (segmentos.length < 3) {
    respuesta = 'Formato incorrecto.\n\n' +
      'Usa: *pedido Nombre, Tel\u00e9fono, productos*\n' +
      '_Ejemplo: pedido Juan, 0414-123, 2 TUB001, 5 SLA002_';
  } else {
    const nombre = segmentos[0];
    const tel = segmentos[1];
    const prods = segmentos.slice(2).join(', ');
    needsAPI = true;
    apiUrl = API + '/api/wa/pedido?nombre=' + encodeURIComponent(nombre) +
      '&tel=' + encodeURIComponent(tel) +
      '&items=' + encodeURIComponent(prods) +
      '&wa=' + phone;
    args = JSON.stringify({ nombre, tel, items: prods });
  }

} else {
  intent = 'default';
  respuesta = 'No entend\u00ed \"' + text + '\".\n\nEscribe *menu* para ver las opciones.';
}

return [{ json: { phone, respuesta, needsAPI, apiUrl, intent, args } }];

const items = $input.all();
const apiResp = items[0].json;
const prep = $('Preparar').first().json;
const intent = prep.intent;

let respuesta = '';

try {
  if (intent === 'catalogo' || intent === 'buscar') {
    const productos = apiResp.productos || [];
    if (productos.length > 0) {
      const titulo = intent === 'buscar'
        ? '*\ud83d\udd0d Resultados para \"' + prep.args + '\"*'
        : '*\ud83d\udce6 Cat\u00e1logo de Productos*';
      respuesta = titulo + '\n\n';
      for (const p of productos) {
        respuesta += '*' + p.codigo + '* \u2014 ' + p.descripcion + '\n';
        respuesta += '   ' + (p.unidad ? p.unidad + ' \u00b7 ' : '') + '$' + Number(p.precio).toFixed(2) + '\n\n';
      }
      respuesta += '_Escribe *3 [c\u00f3digo]* para m\u00e1s detalles o *5* para pedir_';
    } else {
      respuesta = intent === 'buscar'
        ? 'No encontr\u00e9 productos con \"' + prep.args + '\".\nPrueba con otro t\u00e9rmino.'
        : 'No hay productos disponibles en este momento.';
    }

  } else if (intent === 'precio') {
    if (apiResp.error) {
      respuesta = 'Producto \"' + prep.args + '\" no encontrado.';
    } else {
      respuesta = '*\ud83d\udcb2 ' + apiResp.descripcion + '*\n\n' +
        'C\u00f3digo: ' + apiResp.codigo + '\n' +
        (apiResp.departamento ? 'Depto: ' + apiResp.departamento + '\n' : '') +
        (apiResp.unidad ? 'Unidad: ' + apiResp.unidad + '\n' : '') +
        'Precio: *$' + Number(apiResp.precio).toFixed(2) + '*';
    }

  } else if (intent === 'abono') {
    if (apiResp.error) {
      respuesta = '\u26a0\ufe0f ' + apiResp.error;
    } else {
      respuesta = '*\ud83d\udcdd Consulta de Cuenta*\n' +
        'Cliente: *' + apiResp.cliente.nombre + '*\n' +
        'RIF: ' + apiResp.cliente.ciRif + '\n\n';
      const facturas = apiResp.facturasPendientes || [];
      if (facturas.length > 0) {
        respuesta += '*Facturas pendientes:*\n';
        for (const f of facturas) {
          const venc = f.vencida ? ' \u26a0\ufe0f VENCIDA' : '';
          respuesta += '\u2022 ' + f.concepto + ': $' + Number(f.saldo).toFixed(2) + venc + '\n';
        }
        respuesta += '\n';
      }
      respuesta += '*Deuda total:* $' + Number(apiResp.totalDeuda).toFixed(2) + '\n';
      respuesta += '*Total abonos:* $' + Number(apiResp.totalAbonos).toFixed(2) + '\n';
      if (apiResp.saldoFavor > 0) {
        respuesta += '*Saldo a favor:* $' + Number(apiResp.saldoFavor).toFixed(2) + '\n';
      }
    }

  } else if (intent === 'pedido') {
    if (apiResp.error) {
      respuesta = '\u26a0\ufe0f ' + apiResp.error;
    } else {
      const datos = JSON.parse(prep.args || '{}');
      respuesta = '*\u2705 Pedido recibido*\n\n' +
        'Cliente: *' + (datos.nombre || '') + '*\n' +
        'Tel: ' + (datos.tel || '') + '\n' +
        'Productos: ' + (datos.items || '') + '\n\n' +
        'Nuestro equipo de ventas se comunicar\u00e1 contigo pronto.\n' +
        '_Escribe *menu* para volver al inicio._';
    }

  } else {
    respuesta = 'Error procesando la solicitud.';
  }
} catch (e) {
  respuesta = 'Ocurri\u00f3 un error. Intenta de nuevo m\u00e1s tarde.';
}

return [{ json: { respuesta } }];
